import { usePage } from '@inertiajs/react';
import type { ReactNode } from 'react';
import { SidebarProvider } from '@/components/ui/sidebar';

type Props = {
    children: ReactNode;
    variant?: 'header' | 'sidebar';
};

/**
 * Root layout shell: sidebar provider or full-width column for header layout.
 * @param {Props} props - Component props.
 * @param {ReactNode} props.children - App chrome and page tree.
 * @param {'header' | 'sidebar'} [props.variant='sidebar'] - Layout mode from shared page props.
 * @returns {JSX.Element}
 */
export function AppShell({ children, variant = 'sidebar' }: Props) {
    const isOpen = usePage().props.sidebarOpen;

    if (variant === 'header') {
        return (
            <div className="flex min-h-screen w-full flex-col">{children}</div>
        );
    }

    return (
        <SidebarProvider defaultOpen={isOpen} className="h-svh overflow-hidden">
            {children}
        </SidebarProvider>
    );
}

import * as React from 'react';
import { SidebarInset } from '@/components/ui/sidebar';
import { cn } from '@/lib/utils';

type Props = React.ComponentProps<'main'> & {
    variant?: 'header' | 'sidebar';
};

/**
 * Main content region; uses sidebar inset or centered main depending on layout variant.
 * @param {Props} props - Main element props plus layout variant.
 * @param {'header' | 'sidebar'} [props.variant='sidebar'] - Layout mode (`sidebar` or `header`).
 * @param {React.ReactNode} props.children - Page content.
 * @returns {JSX.Element}
 */
export function AppContent({
    variant = 'sidebar',
    className,
    children,
    ...props
}: Props) {
    if (variant === 'sidebar') {
        // Frame the inset panel: in dark themes it shares the sidebar colour, so without
        // a border the header's bottom rule would end in mid-air.
        return (
            <SidebarInset
                className={cn(
                    'md:peer-data-[variant=inset]:border md:peer-data-[variant=inset]:border-sidebar-border/40',
                    className,
                )}
                {...props}
            >
                {children}
            </SidebarInset>
        );
    }

    return (
        <main
            className={cn(
                'mx-auto flex h-full w-full max-w-7xl flex-1 flex-col gap-4 rounded-xl',
                className,
            )}
            {...props}
        >
            {children}
        </main>
    );
}

import type { ReactNode } from 'react';
import { Breadcrumbs } from '@/components/breadcrumbs';
import type { BreadcrumbItemType } from '@/components/breadcrumbs';
import { SidebarTrigger } from '@/components/ui/sidebar';

/**
 * Top bar inside the sidebar layout with collapse trigger, breadcrumbs, and actions.
 * @param {{ breadcrumbs?: BreadcrumbItemType[], actions?: ReactNode }} props - Component props.
 * @param {BreadcrumbItemType[]} [props.breadcrumbs=[]] - Breadcrumb trail.
 * @param {ReactNode} [props.actions] - Optional right-aligned header actions.
 * @returns {JSX.Element}
 */
export function AppSidebarHeader({
    breadcrumbs = [],
    actions,
}: {
    breadcrumbs?: BreadcrumbItemType[];
    actions?: ReactNode;
}) {
    return (
        <header className="flex h-16 shrink-0 items-center gap-2 border-b border-sidebar-border/40 px-6 transition-[width,height] ease-linear group-has-data-[collapsible=icon]/sidebar-wrapper:h-12 md:px-4">
            <div className="flex min-w-0 flex-1 items-center gap-2 overflow-hidden">
                <SidebarTrigger className="-ml-1 shrink-0" />
                <Breadcrumbs breadcrumbs={breadcrumbs} />
            </div>
            {actions ? (
                <div className="flex min-w-0 shrink-0 items-center justify-end gap-2 overflow-x-auto sm:gap-2">
                    {actions}
                </div>
            ) : null}
        </header>
    );
}

import { Link } from '@inertiajs/react';
import type { InertiaLinkProps } from '@inertiajs/react';
import { Fragment } from 'react';
import { useTranslation } from 'react-i18next';
import { TruncatedText } from '@/components/admin/truncated-text';
import {
    Breadcrumb,
    BreadcrumbItem,
    BreadcrumbLink,
    BreadcrumbList,
    BreadcrumbPage,
    BreadcrumbSeparator,
} from '@/components/ui/breadcrumb';

/**
 * One breadcrumb segment, the starter kit's `BreadcrumbItem` from `@/types`.
 * Declared here because `shadcn add` rewrites `@/types` imports.
 */
export type BreadcrumbItemType = {
    title: string;
    href: NonNullable<InertiaLinkProps['href']>;
};

/**
 * Renders a linked breadcrumb trail from the given items.
 * @param {{ breadcrumbs: BreadcrumbItemType[] }} props - Component props.
 * @param {BreadcrumbItemType[]} props.breadcrumbs - Ordered trail segments (last item is current page).
 * @returns {JSX.Element}
 */
export function Breadcrumbs({
    breadcrumbs,
}: {
    breadcrumbs: BreadcrumbItemType[];
}) {
    const { t } = useTranslation();

    return (
        <>
            {breadcrumbs.length > 0 && (
                <Breadcrumb
                    className="min-w-0"
                    aria-label={t('a11y.breadcrumb')}
                >
                    <BreadcrumbList className="flex-nowrap overflow-hidden">
                        {breadcrumbs.map((item, index) => {
                            const isLast = index === breadcrumbs.length - 1;

                            return (
                                <Fragment key={index}>
                                    <BreadcrumbItem className="max-w-[9rem] min-w-0 shrink md:max-w-[12rem]">
                                        {isLast ? (
                                            <BreadcrumbPage className="block max-w-full min-w-0">
                                                <TruncatedText
                                                    text={item.title}
                                                />
                                            </BreadcrumbPage>
                                        ) : (
                                            <BreadcrumbLink
                                                asChild
                                                className="block max-w-full min-w-0"
                                            >
                                                <Link
                                                    href={item.href}
                                                    className="block max-w-full min-w-0"
                                                >
                                                    <TruncatedText
                                                        text={item.title}
                                                    />
                                                </Link>
                                            </BreadcrumbLink>
                                        )}
                                    </BreadcrumbItem>
                                    {!isLast && <BreadcrumbSeparator />}
                                </Fragment>
                            );
                        })}
                    </BreadcrumbList>
                </Breadcrumb>
            )}
        </>
    );
}

import { useCallback, useLayoutEffect, useRef, useState } from 'react';
import {
    Tooltip,
    TooltipContent,
    TooltipTrigger,
} from '@/components/ui/tooltip';
import { cn } from '@/lib/utils';

type TruncatedTextProps = {
    text: string;
    className?: string;
};

/**
 * CSS truncate with tooltip only when the text actually overflows.
 */
export function TruncatedText({ text, className }: TruncatedTextProps) {
    const ref = useRef<HTMLSpanElement>(null);
    const [truncated, setTruncated] = useState(false);

    const measure = useCallback(() => {
        const el = ref.current;

        if (!el) {
            return;
        }

        setTruncated(el.scrollWidth > el.clientWidth + 1);
    }, []);

    useLayoutEffect(() => {
        measure();

        const el = ref.current;

        if (!el || typeof ResizeObserver === 'undefined') {
            return;
        }

        const observer = new ResizeObserver(() => measure());
        observer.observe(el);

        return () => observer.disconnect();
    }, [measure, text]);

    return (
        <Tooltip>
            <TooltipTrigger asChild>
                <span
                    ref={ref}
                    className={cn('block min-w-0 truncate', className)}
                >
                    {text}
                </span>
            </TooltipTrigger>
            {truncated ? (
                <TooltipContent className="max-w-sm break-words">
                    {text}
                </TooltipContent>
            ) : null}
        </Tooltip>
    );
}
